    edu4B: 'உங்கள் மொழியில் எப்போது வேண்டுமானாலும் மீராவுடன் பேசுங்கள். அவள் கேட்கிறாள், நினைவில் வைக்கிறாள், ஆதரிக்கிறாள் — ஒருபோதும் தீர்ப்பளிக்கவில்லை.',
    tourTitle: 'மீராவுக்கு வரவேற்கிறோம்',
    tourSub: 'நீங்கள் என்ன செய்யலாம் என்பதை ஆராய்வோம்.',
    takeTour: 'சுற்றுப்பயணம் மேற்கொள்',
    skipTour: 'இப்போதைக்கு தவிர்',
    tourStart: 'மீராவைப் பயன்படுத்தத் தொடங்கு',
    tourOpen: 'இப்போது திற',
    tourTrackerD: 'மாதவிடாய் தேதிகளைப் பதிவு செய்து உங்கள் சுழற்சி நாள், கட்டம், அடுத்த மாதவிடாய் மற்றும் ஒழுங்கைப் பாருங்கள் — அனைத்தும் உங்கள் தரவிலிருந்து.',
    tourVoiceD: 'உங்கள் மொழியில் மீராவுடன் பேசுங்கள், அவள் உரையாடலை ஒரு கட்டமைக்கப்பட்ட ஆரோக்கியப் பதிவாக மாற்றுகிறாள்.',
    tourGuideD: 'மாதவிடாய், ஹார்மோன்கள் மற்றும் உங்கள் உடல் பற்றிய அன்பான, தீர்ப்பில்லா பதில்கள் — நீங்கள் தேவைப்படும் போதெல்லாம்.',
    tourReportD: 'மாதக்கணக்கான பதிவுகளையும் அறிகுறிகளையும் உங்கள் மருத்துவர் நொடிகளில் படிக்கக்கூடிய தெளிவான சுருக்கமாக மாற்றுங்கள்.',
    tourCondD: 'PCOS, தைராய்டு, எண்டோமெட்ரியோசிஸ் மற்றும் பலவற்றுடன் தொடர்புடைய முறைகளை அடையாளம் காணுங்கள் — ஒரு வழிகாட்டி, நோய் கண்டறிதல் அல்ல.',
    tourSettingsD: 'உங்கள் ஆப் மொழி, நினைவூட்டல்கள், அவசர தொடர்பு மற்றும் தரவை எப்போது வேண்டுமானாலும் மாற்றவும்.',
