    phaseMsgFollicular: 'நீங்கள் ஃபாலிகுலர் கட்டத்தில் இருக்கிறீர்கள் — இப்போது உங்கள் ஆற்றல் பொதுவாக அதிகரிக்கும்.',
    phaseMsgOvulation: 'நீங்கள் அண்டவிடுப்பு காலத்தில் இருக்கிறீர்கள் — இன்று மிகவும் ஆற்றலுடன் உணரலாம்.',
    phaseMsgLuteal: 'நீங்கள் லூடியல் கட்டத்தில் இருக்கிறீர்கள் — மெதுவாக இருந்து ஆறுதலுக்கு முன்னுரிமை கொடுங்கள்.',
    phaseMsgNoData: 'டிராக்கரில் உங்கள் மாதவிடாயைப் பதிவு செய்யுங்கள், மீரா உங்கள் நாளை தனிப்பயனாக்கும்.',
    insightPain: 'சமீபத்தில் சிறிது வலியைக் குறிப்பிட்டீர்கள். ஒரு சிறு நடை, வெப்பம் மற்றும் நீரேற்றம் இன்று நன்றாக உணர உதவும்.',
    insightMenstrual: 'இரும்புச்சத்து உணவும் ஓய்வும் இந்தக் கட்டத்தை எளிதாக்கும். உங்களிடம் அன்பாக இருங்கள் — ஒரு சூடான பானமும் உதவும்.',
    insightFollicular: 'இப்போது ஆற்றல் அதிகரிக்கும் — உடற்பயிற்சி மற்றும் புதிதாக ஏதாவது முயற்சிக்க நல்ல நேரம்.',
    insightOvulation: 'இன்று மிகவும் சமூகமாகவும் ஆற்றலுடனும் உணரலாம். நீரேற்றத்துடன் இருந்து அனுபவியுங்கள்.',
