    darkDefault: 'இருண்ட பயன்முறை மீராவின் இயல்புநிலை தீம்.',
    dataDesc:
      'உங்கள் ஆரோக்கியத் தரவு இந்தச் சாதனத்தில் சேமிக்கப்படுகிறது (இணைக்கப்பட்டால் Appwrite இலும்). எப்போது வேண்டுமானாலும் நீக்கலாம் — இது ஒவ்வொரு உள்ளூர் பதிவையும் உண்மையாக நீக்குகிறது.',
    deleteData: 'என் தரவை நீக்கு',
    accountSync: 'கணக்கு ஒத்திசைவு (Appwrite)',
    connBadgeAuthData: 'இணைக்கப்பட்டது (அங்கீகாரம் + தரவு)',
    connBadgeAuth: 'இணைக்கப்பட்டது (அங்கீகாரம்)',
    connBadgeNone: 'இணைக்கப்படவில்லை',
    accountSyncDesc:
      'உண்மையான கணக்குகள் மற்றும் கிளவுட் ஒத்திசைவை இயக்க உங்கள் Appwrite Project ID ஐ ஒட்டவும். எண்ட்பாயிண்ட் மற்றும் project id பொது (ரகசியம் அல்ல). சாதனங்களில் உங்கள் பதிவுகளை ஒத்திசைக்க Database ID ஐயும் சேர்க்கவும்.',
    connectReload: 'இணைத்து மீண்டும் ஏற்று',
    disconnect: 'துண்டி',
    symTitle: 'அறிகுறி டிராக்கர்',
    symIntro:
      'நீங்கள் கவனித்த அறிகுறிகளைத் தேர்ந்தெடுக்கவும். காலப்போக்கில் அவற்றைப் பதிவு செய்வது மகப்பேறு மருத்துவரிடம் காட்ட ஒரு தெளிவான படத்தை உருவாக்கும் — இது ஒரு வழிகாட்டி, நோய் கண்டறிதல் அல்ல.',
    symTracked: 'அறிகுறிகள் பதிவு',
    symSummary0: 'இன்னும் எதுவும் தேர்ந்தெடுக்கப்படவில்லை. பதிவு செய்யத் தொடங்க கீழே உள்ள எந்த அறிகுறியையும் தட்டவும்.',
    symSummaryMany:
      'பல அறிகுறிகள் குறிக்கப்பட்டுள்ளன. ஒரு சுகாதார நிபுணருடன் PCOS/PCOD பரிசோதனை பற்றி பேசுவதைக் கருதுங்கள் — இது ஒரு அபாய அறிகுறி, நோய் கண்டறிதல் அல்ல.',
    symSummaryFew: 'எந்த அறிகுறிகள் தொடர்கின்றன என்பதைப் பார்க்க சில சுழற்சிகள் தொடர்ந்து பதிவு செய்யுங்கள்.',
