    symSleep: 'தூக்கப் பிரச்சினைகள்',
    symSafety:
      'மீரா PCOS அல்லது PCOD ஐ கண்டறியவில்லை. நோய் கண்டறிதலுக்கு மருத்துவ மதிப்பீடு தேவை (பெரும்பாலும் அல்ட்ராசவுண்ட் மற்றும் இரத்தப் பரிசோதனைகள் உட்பட). உங்கள் அனுபவத்தை மருத்துவரிடம் தெளிவாக விவரிக்க இந்த டிராக்கரைப் பயன்படுத்தவும். உங்கள் தேர்வுகள் உங்கள் சாதனத்தில் தனிப்பட்டதாகச் சேமிக்கப்படுகின்றன.',
    rptTitle: 'ஆரோக்கிய சுருக்க அறிக்கை',
    rptSub: 'மருத்துவருக்குத் தயார். பகிர அச்சிடவும் அல்லது PDF ஆகச் சேமிக்கவும்.',
