    ftDocSumP2: 'அறிக்கை கண்டுபிடிப்புகள் சேர்க்கப்பட்டுள்ளன',
    ftDocSumP3: 'PDF ஆக ஏற்றுமதி',
    ftCommT: 'சமூக நுண்ணறிவு',
    ftCommB: 'ஒரு தனிநபரை ஒருபோதும் வெளிப்படுத்தாத அநாமதேய, மக்கள்தொகை அளவிலான நுண்ணறிவுகள் — k≥10 அடக்குமுறை வரம்பால் பாதுகாக்கப்பட்டு, தெரியும் தனியுரிமை பேட்ஜுடன் காட்டப்படுகிறது.',
