    ftCommP2: 'k≥10 அடக்குமுறை (வேறுபட்ட தனியுரிமை அல்ல)',
    ftCommP3: '"k-அநாமதேயத்தால் பாதுகாக்கப்பட்டது" குறிகாட்டி',
    ftSustT: 'நிலைத்தன்மை',
    ftSustB: 'வெளியிடப்பட்ட வாழ்க்கைச் சுழற்சி மதிப்பீட்டுத் தரவைப் பயன்படுத்தி, உங்கள் தயாரிப்பு தேர்வுகளின் மாதிரி சுற்றுச்சூழல் தடத்தைப் பாருங்கள் — சென்சார் அளவிடப்பட்டதல்ல, மாதிரி என தெளிவாகக் குறிக்கப்பட்டுள்ளது.',
    ftSustP1: 'உங்கள் பதிவு செய்யப்பட்ட தயாரிப்பு வகையின் அடிப்படையில்',
    ftSustP2: 'மேற்கோள் காட்டப்பட்ட உமிழ்வு காரணிகள்',
    ftSustP3: 'வெளிப்படையான முறையியல் குறிப்பு',
    ftPrivateT: 'வடிவமைப்பால் எப்போதும் தனிப்பட்டது',
    ftPrivateB: 'உங்கள் குரல் படியெடுக்கப்பட்டு அகற்றப்படுகிறது — ஒருபோதும் சேமிக்கப்படவில்லை. உங்கள் தரவு உங்களுடையது: குறியாக்கப்பட்டது, உங்களுக்கு மட்டுமே அனுமதிக்கப்பட்டது, தேவைப்படும்போது நீக்கக்கூடியது.',
    ftHowItWorks: 'இது எப்படி வேலை செய்கிறது',
    cndBadge: 'குறிப்பு',
    cndTitle: 'நிலைமைகள் & மாதவிடாய் மாற்றங்கள்',
    cndSub: 'மாதவிடாய் மாற்றங்களுடன் தொடர்புடைய பொதுவான நிலைமைகள், அவை பெரும்பாலும் காட்டும் அறிகுறிகள், மற்றும் அவற்றை சிகிச்சை செய்யும் நிபுணர் வகை. இது முறைகளை அடையாளம் காண ஒரு வழிகாட்டி — ஒருபோதும் நோய் கண்டறிதல் அல்ல.',
    cndThCondition: 'நிலைமை',
