    cnd3n: 'எண்டோமெட்ரியோசிஸ்', cnd3m: 'மிகவும் வலிமிகுந்த மாதவிடாய்', cnd3o: 'இடுப்பு வலி, உடலுறவின்போது வலி, மலட்டுத்தன்மை', cnd3s: 'மகப்பேறு மருத்துவர்',
    cnd4n: 'கருப்பை நார்த்திசுக் கட்டிகள்', cnd4m: 'அதிக இரத்தப்போக்கு', cnd4o: 'இடுப்பு அழுத்தம், நீண்ட மாதவிடாய்', cnd4s: 'மகப்பேறு மருத்துவர்',
    cnd5n: 'அடினோமயோசிஸ்', cnd5m: 'அதிக, வலிமிகுந்த மாதவிடாய்', cnd5o: 'விரிந்த கருப்பை, கடுமையான வயிற்று வலி', cnd5s: 'மகப்பேறு மருத்துவர்',
