    nuPcosNote: 'PCOS-விழிப்புணர்வு திட்டம்: இரத்த சர்க்கரையை சமநிலைப்படுத்த குறைந்த-GI உணவுகள், புரதம், நார்ச்சத்து மீது கவனம். சுத்திகரிக்கப்பட்ட சர்க்கரை, மைதாவைக் குறைக்கவும்.',
