    nuWhyIron: 'மாதவிடாய் பயன்படுத்தும் இரும்பை நிரப்ப இரும்புச்சத்து நிறைந்தது.', nuWhyComfort: 'உங்கள் உடலுக்கு இதமான சிறு ஆறுதல்.', nuWhyWarm: 'வயிற்று வலியைக் குறைக்க சூடும் ஆறுதலும்.', nuWhyHydrate: 'நீரேற்றமாக வைத்து வீக்கத்தைக் குறைக்கும்.', nuWhyAnti: 'உடலை அமைதிப்படுத்தும் அழற்சி எதிர்ப்பு.',
