    sosDisclaimer: 'MIRA அவசர சேவைகளுக்கு மாற்று அல்ல. உண்மையான அவசரத்தில், உடனடியாக உங்கள் உள்ளூர் அவசர எண்ணை அழைக்கவும்.',
