    safyCheckinSub: 'நீங்கள் எப்போது வருவீர்கள் என்று MIRA-விடம் சொல்லுங்கள். நீங்கள் பதிவு செய்யாவிட்டால், உங்கள் தொடர்புக்கு அறிவிக்க உதவுவோம்.', safyNeedContact: 'முதலில் ஒரு பராமரிப்பு வட்டத் தொடர்பைச் சேர்க்கவும்.', safyMin: 'நிமிடம்', safyCheckinExpired: 'உங்கள் பதிவு நேரம் முடிந்தது. நீங்கள் நலமா?', safyNotifyNow: 'தொடர்புக்கு அறிவி', safyImOk: 'நான் நலம்', safyCheckinActive: 'பதிவு செய்கிறது', safyImSafe: 'நான் பாதுகாப்பாக இருக்கிறேன்', safyCheckinMsg: 'நான் சரியான நேரத்தில் பதிவு செய்யவில்லை — தயவுசெய்து என்னைச் சரிபார்க்கவும்.',
