    aiPipeKnowledge: 'தொடர்புடைய, ஆதாரம் காட்டப்பட்ட கல்வியை மீட்டெடுக்கிறது (நோயறிதல் அல்ல)',
    aiPipeSafety: 'பாதுகாப்புச் சோதனை — நெருக்கடி ஆதரவு, அச்சமில்லை, நோயறிதல் இல்லை',
    aiPipeResponse: 'உங்கள் மொழியில் அன்புடன் பதிலளித்து ஏன் என்று விளக்குகிறது',
    aiGuardrails: 'பாதுகாப்பு எல்லைகள்',
    aiGuard1: 'ஒருபோதும் நோயறியாது — பொது கல்வியை மட்டுமே பகிர்கிறது.',
    aiGuard2: 'தேவைப்படும்போது எப்போதும் தொழில்முறை பராமரிப்பை ஊக்குவிக்கிறது.',
    aiGuard3: 'அச்சம் அல்லது இழிவான மொழியை ஒருபோதும் பயன்படுத்தாது.',
    aiGuard4: 'ஏதேனும் நிச்சயமற்றால் அதைச் சொல்கிறது — உண்மைகளைக் கற்பனை செய்யாது.',
    aiGuard5: 'அவசரமாகத் தோன்றும் அறிகுறிகளை அவசர உதவிக்கு அனுப்புகிறது.',
    aiSources: 'அதன் அறிவு எங்கிருந்து வருகிறது',
    aiSourcesNote: 'நம்பகமான கல்வி ஆதாரங்களிலிருந்து எடுக்கப்பட்ட சுருக்கமான, எளிய மொழி சுருக்கங்கள்:',
    aiMemory: 'நினைவகம் & தனியுரிமை',
    aiMemoryNote: 'உங்கள் பராமரிப்பைத் தனிப்பயனாக்க உதவுவதை மட்டுமே MIRA நினைவில் வைக்கிறது — உங்கள் சாதனத்தில். MIRA மையத்திலிருந்து அனைத்தையும் பார்க்கலாம், இடைநிறுத்தலாம், மீட்டமைக்கலாம் அல்லது ஏற்றுமதி செய்யலாம்.',
    aiManageMemory: 'நினைவகத்தை நிர்வகி',
    // ── Part 18: Operations Console ──────────────────────────────────────────
    admTitle: 'செயல்பாட்டு பலகை', admSub: 'MIRA-வை நிர்வகிக்கவும் — பயனர்கள், AI, உள்ளடக்கம், நிபுணர்கள் — குறியீடு மாற்றமின்றி.', admDemo: 'மாதிரி தரவு',
