    roleSuper: 'சூப்பர் நிர்வாகி', roleAdmin: 'நிர்வாகி', roleMod: 'மதிப்பீட்டாளர்', roleDoctor: 'மருத்துவர்', roleNutri: 'ஊட்டச்சத்து நிபுணர்',
