    fcMoodMenstrual: 'உங்கள் மனநிலை மென்மையாக உணரலாம். இது மெதுவாகி உங்களிடம் கருணையாக இருக்க இயற்கையான நேரம்.',
    fcEnergyFollicular: 'உங்கள் ஃபாலிகுலர் கட்டம் தொடங்கும்போது ஆற்றல் உயர வாய்ப்புள்ளது — ஒரு பிரகாசமான, திறமையான வாய்ப்பு.',
    fcMoodFollicular: 'இப்போது மனநிலை பெரும்பாலும் பிரகாசமாகி, அதிக ஊக்கமும் சமூக பொறியும் வரும்.',
    fcCravingsLow: 'இங்கு ஆசைகள் குறைவாக இருக்கும் — நிலையான, ஊட்டமளிக்கும் உணவுகளுக்கு நல்ல நேரம்.',
