    hcRx: 'மருந்துச்சீட்டுகள்', hcRxFrom: '{name}-இடமிருந்து', hcSigned: 'கையொப்பமிடப்பட்டது',
    hcSharing: 'மருத்துவர்களுடன் பகிரப்பட்டது', hcNoShares: 'நீங்கள் இன்னும் எந்தப் பதிவையும் பகிரவில்லை.', hcShareInfo: '{n} பிரிவுகள் · {date} வரை அணுகல்', hcRevoke: 'நீக்கு',
    hcSharingNote: 'ஒவ்வொரு மருத்துவரும் எந்தப் பதிவுகளைப் பார்க்கிறார், எவ்வளவு நேரம் என்பதை நீங்கள் கட்டுப்படுத்துகிறீர்கள். ஒரே தட்டில் அணுகலை நீக்குங்கள் — உங்கள் தரவு உங்கள் சாதனத்தில் மறையாக்கப்பட்டு இருக்கும்.',
    hcAccessLog: 'அணுகல் வரலாறு', logAct_apptBooked: '{name} உடன் ஒரு சந்திப்பைப் பதிவு செய்தது', logAct_consultDone: '{name} உடன் ஒரு ஆலோசனையை முடித்தது', logAct_shared: '{name} உடன் {n} பிரிவுகளைப் பகிர்ந்தது', logAct_revoked: '{name}-இன் அணுகலை நீக்கியது',
    hcTimeline: 'ஆரோக்கிய பதிவு காலவரிசை', rtConsult: '{name} உடன் ஆலோசனை', rtAppt: '{name} உடன் சந்திப்பு பதிவு', rtRx: 'மருந்துச்சீட்டு வழங்கப்பட்டது', rtPlan: 'கவனிப்புத் திட்டம் உருவாக்கப்பட்டது', rtLog: 'ஒரு பதிவு செய்யப்பட்டது',
