    reBadge: 'ஆராய்ச்சி தளம்', reTitle: 'ஆராய்ச்சி, உங்கள் விதிமுறைகளில்', reSub: 'பெண்கள் நலனை முன்னேற்ற உதவுங்கள் — அநாமதேயமாக, தன்னார்வமாக, எப்போதும் உங்கள் வெளிப்படையான சம்மதத்துடன் மட்டுமே.',
    reDisclaimer: 'பங்கேற்பு எப்போதும் விருப்பமானது, திரும்பப்பெறக்கூடியது. நீங்கள் ஒப்புக்கொள்ளாத வரை எதுவும் உங்கள் சாதனத்தை விட்டு வெளியேறாது, இங்கே காட்டப்படும் மக்கள்தொகை புள்ளிவிவரங்கள் மாதிரி மொத்தங்கள் — உண்மையான தனிநபர்கள் அல்ல.',
    reTabPart: 'பங்கேற்பு', reTabStudies: 'ஆய்வுகள்', reTabInsights: 'நுண்ணறிவுகள்',
    rePartActive: 'நீங்கள் ஆராய்ச்சிக்கு பங்களிக்கிறீர்கள்', rePartActiveSub: '{n} சம்மத நிலை(கள்) செயலில். நன்றி — எந்த நேரத்திலும் இடைநிறுத்தலாம் அல்லது வெளியேறலாம்.', rePartOff: 'எதுவும் பகிரப்படவில்லை', rePartOffSub: 'நீங்கள் எந்த ஆராய்ச்சி பங்கேற்பையும் இயக்கவில்லை. அனைத்தும் உங்கள் சாதனத்தில் இருக்கும்.',
    reConsentLevels: 'சம்மத நிலைகள்', reConsentIntro: 'விரிவான, திரும்பப்பெறக்கூடியது — நீங்கள் வசதியாக இருப்பதை மட்டும் இயக்குங்கள். ஒவ்வொரு நிலையும் இயல்பாக அணைக்கப்பட்டுள்ளது.',
    rsL1: 'நிலை 1 · அநாமதேய பயன்பாடு', rsL1Desc: 'அனுபவத்தை மேம்படுத்த அநாமதேய ஆப் பயன்பாட்டு பகுப்பாய்வு (பார்வையிட்ட திரைகள், பயன்படுத்திய அம்சங்கள்). ஆரோக்கிய தரவு இல்லை.',
    rsL2: 'நிலை 2 · அநாமதேய ஆரோக்கிய போக்குகள்', rsL2Desc: 'உங்களை ஒருபோதும் அடையாளம் காணாத மொத்த, அடையாளம் நீக்கப்பட்ட ஆரோக்கிய போக்குகள் (எ.கா. சராசரி சுழற்சி நீளம்).',
    rsL3: 'நிலை 3 · ஆராய்ச்சி பங்கேற்பு', rsL3Desc: 'குறிப்பிட்ட, நெறிமுறை-மதிப்பாய்வு செய்யப்பட்ட ஆய்வுகளில் சேருங்கள். ஒவ்வொன்றையும் நீங்கள் தேர்வு செய்து எந்த நேரத்திலும் விலகலாம்.',
    rsL4: 'நிலை 4 · மருத்துவ ஆய்வு அழைப்புகள்', rsL4Desc: 'தகுதியான மருத்துவ ஆய்வுகளுக்கான அழைப்புகளைப் பெறுங்கள். அழைப்புகள் மட்டுமே — சேர்வது எப்போதும் தனி தேர்வு.',
    rsL5: 'நிலை 5 · AI மாதிரி மேம்பாடு', rsL5Desc: 'தனியுரிமை-பாதுகாக்கும் நுட்பங்களைப் பயன்படுத்தி MIRA-வின் AI-ஐ மேம்படுத்த அநாமதேய, சம்மதிக்கப்பட்ட தொடர்புகளை அனுமதியுங்கள்.',
    reAnon: 'அநாமதேயமாக்கும் இயந்திரம்', reAnonIntro: 'ஆராய்ச்சிக்கு எதையும் பயன்படுத்துவதற்கு முன், அடையாளம் காணும் விவரங்கள் உங்கள் சாதனத்தில் நீக்கப்படுகின்றன. உங்கள் தரவுக்கு என்ன நடக்கிறது என்பது இதோ:',
    reAnonRemoved: 'நீக்கப்பட்டது', reAnonKept: 'வைக்கப்பட்டது (அநாமதேயம்)', reAnonNote: 'உங்கள் அநாமதேய ID-ஐ உங்களிடம் திரும்பக் கண்டுபிடிக்க முடியாது. நீக்கம் சாதனத்தில், தரவு மொத்தப்படுத்தப்படுவதற்கு முன் நடக்கிறது.',
