    edu3T: 'ആശ്വാസവും പരിചരണവും',
    edu3B: 'വിശ്രമം, ഇരുമ്പ് സമ്പന്ന ഭക്ഷണം, ചൂട് എന്നിവ വയറുവേദന കുറയ്ക്കുന്നു. ഏതാനും മണിക്കൂറുകൾ കൂടുമ്പോൾ പാഡോ കപ്പോ മാറ്റുക. ചെറിയ ശീലങ്ങൾ വലിയ മാറ്റം ഉണ്ടാക്കുന്നു.',
    edu4T: 'മീര നിങ്ങൾക്കൊപ്പമുണ്ട്',
    edu4B: 'നിങ്ങളുടെ ഭാഷയിൽ എപ്പോൾ വേണമെങ്കിലും മീരയോട് സംസാരിക്കുക. അവൾ കേൾക്കുന്നു, ഓർക്കുന്നു, പിന്തുണയ്ക്കുന്നു — ഒരിക്കലും വിധിക്കുന്നില്ല.',
    tourTitle: 'മീരയിലേക്ക് സ്വാഗതം',
    tourSub: 'നിങ്ങൾക്ക് എന്തൊക്കെ ചെയ്യാമെന്ന് നോക്കാം.',
    takeTour: 'ടൂർ എടുക്കുക',
    skipTour: 'ഇപ്പോൾ ഒഴിവാക്കുക',
    tourStart: 'മീര ഉപയോഗിച്ച് തുടങ്ങുക',
    tourOpen: 'ഇപ്പോൾ തുറക്കുക',
    tourTrackerD: 'ആർത്തവ തീയതികൾ രേഖപ്പെടുത്തി നിങ്ങളുടെ ചക്ര ദിവസം, ഘട്ടം, അടുത്ത ആർത്തവം, ക്രമം എന്നിവ കാണുക — എല്ലാം നിങ്ങളുടെ ഡാറ്റയിൽ നിന്ന്.',
    tourVoiceD: 'നിങ്ങളുടെ ഭാഷയിൽ മീരയോട് സംസാരിക്കുക, അവൾ സംഭാഷണത്തെ ഒരു ഘടനാപരമായ ആരോഗ്യ രേഖയാക്കി മാറ്റുന്നു.',
    tourGuideD: 'ആർത്തവം, ഹോർമോണുകൾ, നിങ്ങളുടെ ശരീരം എന്നിവയെക്കുറിച്ച് ഊഷ്മളവും വിധിയില്ലാത്തതുമായ ഉത്തരങ്ങൾ — എപ്പോൾ വേണമെങ്കിലും.',
    tourReportD: 'മാസങ്ങളുടെ രേഖകളും ലക്ഷണങ്ങളും നിങ്ങളുടെ ഡോക്ടർക്ക് സെക്കൻഡുകളിൽ വായിക്കാവുന്ന വൃത്തിയുള്ള സംഗ്രഹമാക്കി മാറ്റുക.',
    tourCondD: 'PCOS, തൈറോയ്ഡ്, എൻഡോമെട്രിയോസിസ് തുടങ്ങിയവയുമായി ബന്ധപ്പെട്ട മാതൃകകൾ തിരിച്ചറിയുക — ഒരു വഴികാട്ടി, രോഗനിർണയമല്ല.',
    tourSettingsD: 'നിങ്ങളുടെ ആപ്പ് ഭാഷ, ഓർമ്മപ്പെടുത്തലുകൾ, അടിയന്തര ബന്ധം, ഡാറ്റ എന്നിവ എപ്പോൾ വേണമെങ്കിലും മാറ്റുക.',
