    insightPain: 'അടുത്തിടെ നിങ്ങൾ കുറച്ച് വേദന കുറിച്ചു. ഒരു ചെറിയ നടത്തം, ചൂട്, വെള്ളം കുടിക്കൽ എന്നിവ ഇന്ന് മെച്ചപ്പെടാൻ സഹായിക്കും.',
    insightMenstrual: 'ഇരുമ്പ് സമ്പന്ന ഭക്ഷണവും വിശ്രമവും ഈ ഘട്ടം എളുപ്പമാക്കും. സ്വയം ദയ കാണിക്കൂ — ഒരു ചൂടുള്ള പാനീയവും സഹായിക്കും.',
    insightFollicular: 'ഇപ്പോൾ ഊർജ്ജം കൂടും — വ്യായാമത്തിനും പുതിയത് പരീക്ഷിക്കാനും നല്ല സമയം.',
    insightOvulation: 'ഇന്ന് നിങ്ങൾക്ക് ഏറ്റവും സാമൂഹികവും ഊർജ്ജസ്വലവുമായി തോന്നാം. വെള്ളം കുടിച്ച് ആസ്വദിക്കൂ.',
    insightLuteal: 'ആർത്തവത്തിന് മുമ്പ് PMS പ്രത്യക്ഷപ്പെടാം. സൗമ്യമായ ചലനവും നേരത്തെയുള്ള ഉറക്കവും സഹായിക്കും.',
