    cnd2n: 'പോളിസിസ്റ്റിക് ഓവേറിയൻ രോഗം (PCOD)', cnd2m: 'ക്രമരഹിത ആർത്തവം', cnd2o: 'ഭാരം കൂടൽ, മുഖക്കുരു, അണ്ഡാശയ സിസ്റ്റുകൾ', cnd2s: 'ഗൈനക്കോളജിസ്റ്റ്',
