    eduDone: 'ముగించు',
    skip: 'దాటవేయి',
    edu1T: 'మీ చక్రం, వివరించబడింది',
    edu1B: 'మీ రుతుక్రమ చక్రం ఒక నెలవారీ లయ — కేవలం మీ పీరియడ్ కాదు. మీర కాలక్రమేణా మీది నేర్చుకుని ఒకే చోట ఉంచుతుంది.',
    edu2T: 'నాలుగు దశలు',
    edu2B: 'రుతుక్రమం, ఫాలిక్యులర్, అండోత్సర్గం, ల్యూటియల్ — ప్రతి ఒక్కటి వేర్వేరు శక్తి, మానసిక స్థితి మరియు అవసరాలను తెస్తుంది. మీరు ఎక్కడ ఉన్నారో మీర చెబుతుంది.',
    edu3T: 'ఓదార్పు & సంరక్షణ',
    edu3B: 'విశ్రాంతి, ఐరన్ అధికంగా ఉండే ఆహారం, వెచ్చదనం తిమ్మిర్లను తగ్గిస్తాయి. ప్రతి కొన్ని గంటలకు ప్యాడ్ లేదా కప్ మార్చండి. చిన్న అలవాట్లు పెద్ద మార్పు తెస్తాయి.',
    edu4T: 'మీర మీతో ఉంది',
    edu4B: 'మీ భాషలో ఎప్పుడైనా మీరతో మాట్లాడండి. ఆమె వింటుంది, గుర్తుంచుకుంటుంది, మద్దతు ఇస్తుంది — ఎప్పుడూ తీర్పు చెప్పదు.',
    tourTitle: 'మీరకు స్వాగతం',
    tourSub: 'మీరు ఏమి చేయగలరో అన్వేషిద్దాం.',
