    tourTrackerD: 'పీరియడ్ తేదీలను నమోదు చేసి మీ చక్ర రోజు, దశ, తదుపరి పీరియడ్ మరియు క్రమబద్ధతను చూడండి — అంతా మీ డేటా నుండి.',
    tourVoiceD: 'మీ భాషలో మీరతో మాట్లాడండి, ఆమె సంభాషణను ఒక నిర్మాణాత్మక ఆరోగ్య లాగ్‌గా మారుస్తుంది.',
    tourGuideD: 'పీరియడ్‌లు, హార్మోన్లు మరియు మీ శరీరం గురించి వెచ్చని, తీర్పు లేని సమాధానాలు — మీకు అవసరమైనప్పుడల్లా.',
    tourReportD: 'నెలల లాగ్‌లు మరియు లక్షణాలను మీ డాక్టర్ సెకన్లలో చదవగల శుభ్రమైన సారాంశంగా మార్చండి.',
    tourCondD: 'PCOS, థైరాయిడ్, ఎండోమెట్రియోసిస్ మరియు మరిన్నింటితో సంబంధమున్న నమూనాలను గుర్తించండి — ఒక గైడ్, రోగనిర్ధారణ కాదు.',
