    ftMemB: 'ప్రతి చెక్-ఇన్ మునుపటిదానిపై నిర్మించబడుతుంది. మీర చక్రాలలో సందర్భాన్ని ఉంచుతుంది, తద్వారా మీ చరిత్ర నిరంతరంగా ఉంటుంది, విడిపోయిన నమోదుల గుట్ట కాదు.',
    ftMemP1: 'చక్రాలలో సందర్భం కొనసాగుతుంది',
    ftMemP2: 'రోలింగ్ విండోలపై లెక్కించిన ట్రెండ్‌లు',
    ftMemP3: 'సందర్శనల మధ్య ఏమీ కోల్పోదు',
    ftDocT: 'డాక్యుమెంట్ ఇంటెలిజెన్స్',
    ftDocB: 'ఒక ల్యాబ్ నివేదికను అప్‌లోడ్ చేయండి, మీర దాన్ని చదువుతుంది — హిమోగ్లోబిన్, ఫెర్రిటిన్, విటమిన్ D మరియు హార్మోన్ విలువలను తీసి మీ ప్రమాద సూచనలలో చేర్చుతుంది.',
    ftDocP1: 'PDF & చిత్ర నివేదికలు',
    ftDocP2: 'ముఖ్య రక్త/హార్మోన్ విలువలను స్వయంచాలకంగా తీస్తుంది',
    ftDocP3: 'తక్కువ ఫెర్రిటిన్ రక్తహీనత సూచనలను బలపరుస్తుంది',
    ftCycleT: 'పీరియడ్ & చక్ర ట్రాకర్',
    ftCycleB: 'పీరియడ్ ప్రారంభ తేదీలను ట్రాక్ చేయండి, మీర మీ చక్ర నిడివి, ప్రస్తుత దశ మరియు తదుపరి అంచనా తేదీని అంచనా వేస్తుంది — అంతా మీ స్వంత లాగ్‌ల నుండి.',
    ftCycleP1: 'నిజమైన డేటా నుండి చక్ర నిడివి & దశ',
    ftCycleP2: 'తదుపరి పీరియడ్ అంచనా',
    ftCycleP3: 'కాలక్రమేణా క్రమబద్ధత సంకేతం',
    ftPcosT: 'PCOS / PCOD లక్షణ ట్రాకింగ్',
    ftPcosB: 'సాధారణ PCOS/PCOD లక్షణాలను కాలక్రమేణా నమోదు చేసి ఏవి కలిసి వస్తాయో చూడండి — గైనకాలజిస్ట్‌కు చూపించడానికి స్పష్టమైన చిత్రం.',
    ftPcosP1: 'మార్గనిర్దేశిత లక్షణ చెక్‌లిస్ట్',
    ftPcosP2: 'వారాలలో నమూనా వీక్షణ',
    ftPcosP3: 'విద్యాపరం, ఎప్పుడూ రోగనిర్ధారణ కాదు',
    ftTrendT: 'ట్రెండ్ ఇంటెలిజెన్స్',
    ftTrendB: 'రోలింగ్ చక్ర నిడివి, నొప్పి మరియు ప్రవాహ ట్రెండ్‌లు చర్చించదగిన నమూనాలను వెలికితీస్తాయి — ఎల్లప్పుడూ ప్రమాద సూచనగా, ఎప్పుడూ రోగనిర్ధారణ కాదు.',
    ftTrendP1: 'రోలింగ్ చక్ర-నిడివి ట్రెండ్',
    ftTrendP2: 'పరస్పర సంబంధాలు: నిద్ర · ఒత్తిడి · నొప్పి',
    ftTrendP3: 'సరళ భాషా వివరణలు',
    ftDocSumT: 'డాక్టర్ సారాంశం',
    ftDocSumB: 'ఒక్క ట్యాప్ నెలల లాగ్‌లను మరియు నివేదిక ఫలితాలను మీ డాక్టర్ సెకన్లలో చదవగల శుభ్రమైన క్లినికల్ సారాంశంగా మారుస్తుంది — ఎగుమతి ఎంపికతో.',
    ftDocSumP1: 'చక్ర & లక్షణ చరిత్ర',
    ftDocSumP2: 'నివేదిక ఫలితాలు చేర్చబడ్డాయి',
    ftDocSumP3: 'PDF కి ఎగుమతి',
    ftCommT: 'కమ్యూనిటీ ఇంటెలిజెన్స్',
    ftCommB: 'ఒక వ్యక్తిని ఎప్పుడూ బహిర్గతం చేయని అనామక, జనాభా-స్థాయి అంతర్దృష్టులు — k≥10 సప్రెషన్ పరిమితి ద్వారా రక్షితం, కనిపించే గోప్యతా బ్యాడ్జ్‌తో చూపబడతాయి.',
    ftCommP1: 'సమూహం & నెల వారీగా సమీకరించబడింది',
    ftCommP2: 'k≥10 సప్రెషన్ (డిఫరెన్షియల్ ప్రైవసీ కాదు)',
    ftCommP3: '"k-అనామకత రక్షితం" సూచిక',
    ftSustT: 'సుస్థిరత',
    ftSustB: 'ప్రచురించిన జీవితచక్ర-మూల్యాంకన డేటాను ఉపయోగించి మీ ఉత్పత్తి ఎంపికల మోడల్ చేసిన పర్యావరణ పాదముద్రను చూడండి — సెన్సార్ కొలిచినది కాదు, మోడల్‌గా స్పష్టంగా లేబుల్ చేయబడింది.',
    ftSustP1: 'మీరు నమోదు చేసిన ఉత్పత్తి రకం ఆధారంగా',
    ftSustP2: 'ఉదహరించిన ఉద్గార కారకాలు',
    ftSustP3: 'పారదర్శక పద్ధతి గమనిక',
    ftPrivateT: 'డిజైన్ ద్వారా ఎల్లప్పుడూ గోప్యం',
    ftPrivateB: 'మీ వాయిస్ ట్రాన్‌స్క్రైబ్ చేసి తొలగించబడుతుంది — ఎప్పుడూ నిల్వ చేయబడదు. మీ డేటా మీది: ఎన్‌క్రిప్టెడ్, మీకు మాత్రమే అనుమతి, అవసరమైనప్పుడు తొలగించదగినది.',
