    edu1B: 'ನಿಮ್ಮ ಮುಟ್ಟಿನ ಚಕ್ರವು ಮಾಸಿಕ ಲಯ — ಕೇವಲ ನಿಮ್ಮ ಮುಟ್ಟು ಅಲ್ಲ. ಮೀರಾ ಕಾಲಕ್ರಮೇಣ ನಿಮ್ಮದನ್ನು ಕಲಿತು ಒಂದೇ ಸ್ಥಳದಲ್ಲಿ ಇಡುತ್ತದೆ.',
    edu2T: 'ನಾಲ್ಕು ಹಂತಗಳು',
    edu2B: 'ಮುಟ್ಟು, ಫಾಲಿಕ್ಯುಲರ್, ಅಂಡೋತ್ಸರ್ಜನ ಮತ್ತು ಲೂಟಿಯಲ್ — ಪ್ರತಿಯೊಂದೂ ವಿಭಿನ್ನ ಶಕ್ತಿ, ಮನಸ್ಥಿತಿ ಮತ್ತು ಅಗತ್ಯಗಳನ್ನು ತರುತ್ತದೆ. ನೀವು ಎಲ್ಲಿದ್ದೀರಿ ಎಂದು ಮೀರಾ ಹೇಳುತ್ತದೆ.',
    edu3T: 'ಆರಾಮ ಮತ್ತು ಆರೈಕೆ',
    edu3B: 'ವಿಶ್ರಾಂತಿ, ಕಬ್ಬಿಣಯುಕ್ತ ಆಹಾರ ಮತ್ತು ಬೆಚ್ಚಗಿನ ಅಂಶ ಸೆಳೆತವನ್ನು ಕಡಿಮೆ ಮಾಡುತ್ತದೆ. ಪ್ರತಿ ಕೆಲವು ಗಂಟೆಗಳಿಗೊಮ್ಮೆ ಪ್ಯಾಡ್ ಅಥವಾ ಕಪ್ ಬದಲಾಯಿಸಿ. ಸಣ್ಣ ಅಭ್ಯಾಸಗಳು ದೊಡ್ಡ ವ್ಯತ್ಯಾಸ ಮಾಡುತ್ತವೆ.',
