    tourVoiceD: 'ನಿಮ್ಮ ಭಾಷೆಯಲ್ಲಿ ಮೀರಾ ಜೊತೆ ಮಾತನಾಡಿ, ಅವಳು ಸಂಭಾಷಣೆಯನ್ನು ರಚನಾತ್ಮಕ ಆರೋಗ್ಯ ದಾಖಲೆಯಾಗಿ ಪರಿವರ್ತಿಸುತ್ತಾಳೆ.',
